non_critical_ambiguity.sql_snippet:
ORDER BY 
    CASE hc.med_urgency ... END ASC,
    recipient_wait_time_ratio DESC;

critical_ambiguity.sql_snippet:
IF NEW."OPER_status" = 'Active'
       AND OLD."OPER_status" != 'Active'
       AND OLD.inspect_status = 'Failed' THEN

        RAISE EXCEPTION 'Cannot activate equipment %. Inspection status is "Failed".', NEW."equipRef";
    END IF;
